%%% Internal functions

check_rate_limit(#state{request_count = Count, rate_limit = Limit, last_reset = LastReset} = State) ->
    Now = erlang:system_time(second),
    case Now - LastReset of
        Diff when Diff >= 60 ->
            {ok, State#state{request_count = 0, last_reset = Now}};
        _ when Count < Limit ->
            {ok, State};
        _ ->
            {error, rate_limited}
    end.

